function vmHHCheck(){if(!document.querySelector(".vm-stage"))return !1;const h=vmHH();if(window.__vmHHu&&Math.abs(h-window.__vmHHu)>6){window.__vmCur=null;rerenderMap();return !0}return !1}
try{document.fonts&&document.fonts.ready.then(()=>setTimeout(vmHHCheck,50))}catch(e){}
