  return S.vlist?`<div class="smap smap-ph">${vPhoneTop(o)}<div class="vp-list vp-plist">${smapOrder().map(vRow).join("")}</div>${vCta()}</div>`:`<div class="smap smap-ph">${vPhoneTop(o)}<div class="smap-sticky"><div class="smap-stage mapbox">${mapSVG(f,{zoom:a>1?{z:a,lon:s.lon,lat:s.lat}:null,aria:"Map of Florida beach towns by style"})}${S.vibe?`<div class="smap-pill"><i class="vdot" style="background:${VCOL[S.vibe]}"></i>${VSHORT[S.vibe]||VIBES[S.vibe]}<small>${o[S.vibe]}</small></div>`:""}<div class="smap-zoom"><button data-mz="in" aria-label="Zoom in">+</button><button data-mz="out" aria-label="Zoom out"${a<=1?" disabled":""}>−</button>${a>1?'<button data-mz="reset" class="rs">Reset</button>':""}</div></div>
  <div class="smap-strip" aria-live="polite"><a class="ss-ph" href="#town-${s.id}" tabindex="-1" aria-hidden="true">${art(s,!1)}</a><div class="ss-bd"><span class="cat">${(regionOf[s.id]||{}).map||s.region}${k>=0?` · ${k+1} of ${n}`:""}</span><b class="ss-nm">${s.name}</b><div class="smap-tags">${s.vibes.slice(0,3).map(tag).join("")}</div></div><div class="ss-row"><button data-step="-1" aria-label="Previous town"${n<2?" disabled":""}>‹</button><a class="btn btn-accent ss-go" href="#town-${s.id}">${short(s).length>14?"Explore this town":"Explore "+short(s)} →</a><button data-step="1" aria-label="Next town"${n<2?" disabled":""}>›</button></div></div></div>${vCta()}</div>`;
