function slLoad(){
  const d={};SLC().forEach(c=>d[c[0]]=slDef(c[0]));
  try{const e=JSON.parse(sessionStorage.getItem(SL_KEY)||"null");
    e&&e.v&&SLC().forEach(c=>{Number.isFinite(e.v[c[0]])&&(d[c[0]]=Math.max(0,Math.min(100,e.v[c[0]])))});
    e&&(S.slPace=null!=e.p?e.p:null,S.slBud=null!=e.b?e.b:null,S.slPc=e.pc||null,S.slPr=e.pr||null,S.slEdu=!!e.e)}catch(e){}
  return d;
}
