/* Score 1 to 5 from the Florida Department of Education grade for the county school district that serves the town: A with 75%+ of schools graded A or B is 5, A is 4, B 3, C 2, D or F 1. */
const eduScore=t=>EDU[t.id]||3;
/* Nov 7 2026: Slider Map sliders. Peace and quiet + Nightlife are one two sided slider (pace, starts in the middle);
   schools are a filter (slTopEdu), not a slider. Everything else starts at 0 and only counts once you push it up. */
const SLC=()=>[["pace","Quiet or lively"],...CATS.filter(c=>"quiet"!==c[0]&&"nightlife"!==c[0]&&"dining"!==c[0]).map(c=>"meet"===c[0]?["meet","Restaurants and community"]:"outdoors"===c[0]?["outdoors","Active outdoors"]:c),["charm","Coastal charm"],["edu","Public schools"]];
/* top school districts: an A district where 85% or more of schools earn an A or B (78 of 167 towns) */
const slTopEdu=e=>{const x=EDUC[e.id];return!!x&&"A"===x[1]&&x[2]>=85};
function pageToggle(cur){return `<nav class="pgtog" aria-label="Explore the coast"><a href="#map" class="${cur==="map"?"on":""}"${cur==="map"?' aria-current="page"':""}>Vibe Map</a><a href="#sliders" class="${cur==="sliders"?"on":""}"${cur==="sliders"?' aria-current="page"':""}>Slider Map</a></nav>`;}
/* ===== Oct 28 2026 patch: home hero A/B test (A = photo hero with buttons, B = live Vibe Map hero) ===== */
/* Assigned 50/50 on the first home page view and kept in localStorage "fc-hero". ?hero=a or ?hero=b forces one.
   Every event and lead from that browser carries "hero=a" or "hero=b" at the end of its utm field. */
function heroVar(assign){
  try{
    const q=new URLSearchParams(location.search).get("hero");
    if(q==="a"||q==="b"){localStorage.setItem("fc-hero",q);return q;}
    let v=localStorage.getItem("fc-hero");
    if(!v&&assign){v=Math.random()<.5?"a":"b";localStorage.setItem("fc-hero",v);}
    return v||null;
  }catch(e){return null;}
}
function fcUtm(u){const v=heroVar();return v?((u?u+"&":"")+"hero="+v).slice(0,300):u;}
/* Towns for the Vibe Map save box: the picked vibe's towns, lead vibe first, then by how many vibes they share. */
function vibeTop(){
  const v=S.vibe;if(!v)return [];
  return T.filter(t=>t.vibes.includes(v)).sort((a,b)=>(b.vibes[0]===v)-(a.vibes[0]===v)||a.vibes.indexOf(v)-b.vibes.indexOf(v)).slice(0,5).map(e=>({e:e,f:null}));
}
let hvSeen=false;
function homeMapFoot(){
  if(!S.vibe)return '<div class="hvhint"><a class="more" href="#map">Open the full Vibe Map</a></div>';
  hvSeen||(hvSeen=true,track("popup_shown","handoff"));
  const nm=VIBES[S.vibe]||"this style",tn=vibeTop().map(x=>short(x.e)),tl=tn.length>1?tn.slice(0,-1).join(", ")+" and "+tn[tn.length-1]:tn[0]||"";
  const save=S.sent.vibe?'<div class="savebox sent" role="status"><b>Saved. Your towns and the guide are on the way.</b><span>Check your inbox in a few minutes (and your spam folder, just in case). Questions? Just reply to that email.</span></div>'
    :`<form class="savebox leadform hvsave" data-lead="matches" data-key="vibe">${hpField}<div class="sv-hd"><b>Keep these towns</b><span><strong>${tl}</strong> in your inbox, each with its prices, flood notes and airport drive, plus our free Move and Belong Guide.</span></div><div class="sv-row"><label for="hv-e" class="sr-only">Your email</label><input id="hv-e" name="email" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com" required><button class="btn btn-accent" type="submit">Send them</button></div><p class="sv-note">Unsubscribe anytime.</p></form>`;
  return `<div class="hvfoot"><div class="hvrank"><div><b>Like ${nm}? Want these ranked for you?</b><span>${SQ.length} taps, 2 minutes, free. We'll score every town on how you want to live.</span></div><a class="btn btn-accent" href="#quiz" data-handoff="1">See my top 5 towns</a></div>${save}<p style="margin-top:14px;text-align:center"><a class="more" href="#map">Open the full Vibe Map</a></p></div>`;
}
document.addEventListener("click",e=>{if(e.target.closest("[data-handoff]"))track("save_tap","handoff")},true);
