function pcredHTML(){const nm=id=>(T.find(t=>t.id===id)||{name:id}).name;return `<h2 id="photo-credits">Photo credits</h2><p>Town photos we did not take ourselves, with thanks to the photographers. Each is used under the license linked.</p><ul class="pcred">${PCRED.slice().sort((a,b)=>nm(a[0]).localeCompare(nm(b[0]))).map(c=>`<li><b>${nm(c[0])}</b>: ${pcE(c[5])}. Photo by ${pcE(c[1])} (<a href="${c[4]}" target="_blank" rel="noopener">source</a>, ${c[3]?`<a href="${c[3]}" target="_blank" rel="noopener">${pcE(c[2])}</a>`:pcE(c[2])}).</li>`).join("")}</ul><h3>Vibe Map photos</h3><ul class="pcred">${VPCRED.map(c=>`<li><b>${pcE(VSHORT[c[0]])}</b>: ${pcE(c[3])}. Photo by ${pcE(c[1])} (<a href="https://unsplash.com/photos/${c[2]}" target="_blank" rel="noopener">source</a>, <a href="https://unsplash.com/license" target="_blank" rel="noopener">Unsplash License</a>).</li>`).join("")}</ul>`}
