function hbResults(){const q=S.q.trim(),nq=sNorm(q),t=T.filter(a=>townMatches(a,q)),rk=e=>{const n=sNorm(short(e));return n===nq?0:n.startsWith(nq)?1:n.includes(nq)?2:searchRank(e,q)+3},L=[...t].sort((a,b)=>rk(a)-rk(b)||short(a).localeCompare(short(b))),lim=S.tlim||24,sh=L.slice(0,lim),lft=L.length-sh.length;
  return`<section class="wrap hb-res"><div class="hb-flag"><h2>${L.length} ${1===L.length?"town":"towns"} matching “${q.replace(/</g,"&lt;")}”</h2><button class="linkbtn hb-clear" data-act="clearsearch">Clear search</button></div>${sh.length?`<div class="hb3-grid ts-grid">${sh.map(e=>hbTile("#town-"+e.id,art(e,!1),short(e),e.blurb,[(regionOf[e.id]||{}).map,MED[e.id]?fmtK(MED[e.id])+" median":"",hbFlood(e.id)].filter(Boolean).join(" · "))).join("")}</div>`:`<p class="hb-none">No towns match that yet. Try a town or area name, or a word like quiet, boating, walkable or affordable.</p>`}${lft>0?`<p class="tmore-wrap"><button class="btn btn-line" data-tmore="1">Show ${Math.min(48,lft)} more of ${L.length}</button></p>`:""}</section>`}
function hbAsk(){return`<section class="wrap hb-ask"><div class="hb-askin"><div><span class="hb-k">When you find one you like</span><h2>See it with someone who lives there</h2><p>Every town page has a way to ask a local. They’ll show you around the way they would a friend. No pressure.</p></div><div class="hb-askb"><a class="btn btn-accent" href="#quiz">Not sure yet? Find my top 5</a><a class="hb-askl" href="#town-destin">Or open any town and tap Ask a local →</a></div></div></section>`}
function arAsk(a,o){const p=o.slice(0,3);return`<section class="wrap hb-ask ar-ask"><div class="hb-askin"><div><span class="hb-k">${a.map}, in person</span><h2>Want to see these towns with a local?</h2><p>Someone who lives here can show you the streets, the water and the parts you won’t find online. No pressure.</p></div><div class="hb-askb">${p.map((e,i)=>`<a class="${i?"btn btn-line":"btn btn-accent"}" href="#contact-${e.id}">Ask a local in ${short(e)}</a>`).join("")}</div></div></section>`}
function regionView(e){const a=REGIONS.find(a=>a.id===e);if(!a)return'<section class="wrap"><h1>Area not found</h1><p><a href="#towns">See all areas</a></p></section>';
  const pos=e=>"panhandle"===a.coast?e.lon:"gulf"===a.coast?-e.lat:"keys"===a.coast?-e.lon:e.lat,dir={panhandle:"west to east",gulf:"north to south",keys:"from Key Largo down",atlantic:"south to north"}[a.coast],t=a.towns.map(e=>byId[e]).filter(Boolean).sort((x,y)=>pos(x)-pos(y)),o=hasW()?[...t].sort((e,a)=>fit(a)-fit(e)):t;
  const ci=COAST_ORDER.findIndex(e=>e[0]===a.coast),cn=COAST_ORDER[ci][1],st=hbStats(t),er=t.map(e=>HEALTH[e.id]&&HEALTH[e.id][1]).filter(e=>null!=e);
  const av=CATS.map((c,i)=>[c,t.reduce((s,e)=>s+(SC[e.id]?SC[e.id][i]:0),0)/t.length]).filter(e=>"airport"!==e[0][0]).sort((x,y)=>y[1]-x[1]).slice(0,3).map(e=>STRENGTH_WORD[e[0][0]]);
  const lst=w=>w.length>2?w.slice(0,-1).join(", ")+" and "+w[w.length-1]:w.join(" and ");
  const facts=[["Homes",hbRange(st)+"<small>median sale prices by town</small>"],["Main airports",st.ap.join(", ")||"Ask a local"],["Nearest ER",er.length?Math.min(...er)+" to "+Math.max(...er)+" miles<small>straight line from town centers</small>":"Ask a local"],["Flood risk",(null==st.fl?"Not scored yet":st.fn>=Math.ceil(t.length/2)?st.fl.toFixed(1)+" of 10 average":"Scored for "+st.fn+" of "+t.length+" towns")+`<small>1 is lowest risk, 10 highest. <a href="#article-flood-risk-rankings">How we score</a></small>`],["Strong on",av.length?lst(av):"Varies"]];
  const hero=`<section class="hb3-hero ar-hero"><div class="hb3-ph">${regionArt(a,!1,!0).replace(' loading="lazy"',"")}</div><div class="wrap hb3-hw"><div class="hb3-panel"><div class="crumbs2"><a href="#home">Home</a> / <a href="#towns">Beach Towns</a> / <a href="#towns" data-hbjump="hb-${a.coast}">${cn.replace(/^The /,"")}</a></div><span class="hb-k">0${ci+1} ${cn.replace(/^The /,"")} · ${t.length} towns</span><h1>${a.map}</h1><p>${a.text}</p></div></div></section>`;
  const strip=`<section class="wrap ar-facts"><dl>${facts.map(f=>`<div><dt>${f[0]}</dt><dd>${f[1]}</dd></div>`).join("")}</dl></section>`;
  const tiles=o.map(e=>hbTile("#town-"+e.id,art(e,!1),short(e),e.blurb,[MED[e.id]?fmtK(MED[e.id])+" median":"",hbFlood(e.id)].filter(Boolean).join(" · ")||"Prices vary, ask a local")).join("");
  const top3=o.slice(0,3);
  const main=`<section class="wrap ar-towns"><div class="hb-flag"><h2>${t.length} towns, ${hasW()?"sorted by your priorities":dir}</h2><a href="#compare?t=${top3.map(e=>e.id).join(",")}">Compare ${top3.map(short).join(", ").replace(/, ([^,]*)$/," and $1")} →</a></div><div class="hb3-grid ar-grid">${tiles}</div></section>`;
  const ri=REGIONS.findIndex(r=>r.id===a.id),sib=REGIONS.filter(r=>r.id!==a.id).sort((x,y)=>Math.abs(REGIONS.indexOf(x)-ri)-Math.abs(REGIONS.indexOf(y)-ri)).slice(0,3),oth=[];
  const more=`<section class="wrap ar-more"><div class="hb-flag"><h2>Nearby areas</h2><a href="#towns">All Beach Towns →</a></div><div class="hb3-grid">${sib.map(r=>{const ts=r.towns.map(x=>byId[x]).filter(Boolean);return hbTile("#region-"+r.id,regionArt(r,!1),r.map,HB_TAG[r.id]||"",ts.length+" towns · "+hbRange(hbStats(ts)))}).join("")}</div><p class="ar-help">Not sure which town fits? <a href="#quiz">Take the 2 minute quiz</a> or <a href="#map">browse by style on the Vibe Map</a>.</p></section>`;
  return hero+strip+main+arAsk(a,o)+more}
const MERGED={"naples-beach":"naples","sarasota-beach":"sarasota","venice-island":"venice","bonita-beach":"bonita-springs","grayton-beach":"30a",seaside:"30a"};function similarTowns(e,a){const t=SC[e.id];return T.filter(a=>a.id!==e.id).map(a=>{const o=SC[a.id];let n=0;for(let e=0;e<t.length;e++)n+=(t[e]-o[e])*(t[e]-o[e]);return{x:a,d:n-(a.coast===e.coast?1.5:0)-(regionOf[a.id].id===regionOf[e.id].id?.5:0)}}).sort((e,a)=>e.d-a.d).slice(0,a||4).map(e=>e.x)}const STRENGTH_WORD={nightlife:"nightlife",meet:"meeting people",quiet:"peace and quiet",walk:"walkability",water:"boating",beach:"beaches",dining:"dining and arts",outdoors:"the outdoors",afford:"affordability",airport:"airport access"};function sharedStrengths(e,a){return CATS.filter(t=>score(e,t[0])>=4&&score(a,t[0])>=4).sort((t,o)=>score(e,o[0])+score(a,o[0])-("airport"===o[0]?4:0)-(score(e,t[0])+score(a,t[0])-("airport"===t[0]?4:0))).map(e=>STRENGTH_WORD[e[0]])}const FAQ_LEAD={walk:["No. Plan on driving for almost everything.","Not really. You will drive for most things.","In parts. Some errands are walkable, most are a short drive.","Yes, for the most part.","Yes. It is one of the most walkable towns on the Florida coast."],beach:["Not really. The beach is not the draw here.","It has a modest one. Better beaches are a drive away.","Yes, a decent one.","Yes, a very good one.","Yes. It is among the best on the Florida coast."],afford:["No. It is one of the most expensive spots on the Florida coast.","It is on the expensive side for the Florida coast.","It sits around the middle for the Florida coast.","Yes, it costs less than most of the Florida coast.","Yes. It is one of the more affordable spots on the Florida coast."],nightlife:["Very quiet. Most of town is dark early.","Quiet, with a handful of places to go.","Good bars and some live music, though it is only busy now and then.","Really good for a beach town.","Big city nightlife, with late hours and plenty of choice."],quiet:["It is busy most of the year.","It gets busy, especially in season.","It is busy in season and calm the rest of the year.","It is quiet most of the year.","It is one of the quietest places on the Florida coast."],water:["Boating is not a big part of life here.","There is some access, but it is limited.","Yes, with decent access to ramps and marinas.","Yes. This is a strong boating town.","Yes. Life here revolves around the water."]};function townFaq(e){const a=STORY[e.id];if(!a)return[];const t=a=>FAQ_LEAD[a][score(e,a)-1],o=short(e),n=SOCIAL[e.id];return[[`Is ${o} walkable?`,`${t("walk")} ${a.walk}`],[`Does ${o} have a good beach?`,`${t("beach")} ${a.beach}`],[`Is ${o} affordable?`,`${t("afford")} ${priceLine(e,1)?`Home prices: ${priceLine(e)}. `:""}${a.afford}`],[`What is the nightlife like in ${o}?`,`${t("nightlife")} ${n&&n.night?n.night:a.nightlife}`],[`How busy does ${o} get?`,`${t("quiet")} ${a.quiet}`],[`Is ${o} good for boating and fishing?`,`${t("water")} ${a.water}`],[`Which airport is closest to ${o}?`,`${a.airport}`],[`What should I know before moving to ${o}?`,`The main things to plan for: ${e.watch.replace(/\.$/,"")}. ${INS}`]]}
