/* Oct 29 2026: map dots are small, so a tap within about 24px (16px with a mouse) of a dot selects the closest town */
document.addEventListener("click",function(e){
  if(!e.isTrusted||!e.target.closest)return;
  var svg=e.target.closest(".mapbox svg");if(!svg||e.target.closest(".dot"))return;
  var R=e.pointerType==="mouse"?16:24,best=null,bd=1e9;
  svg.querySelectorAll(".dot").forEach(function(d){var b=d.getBoundingClientRect(),dx=b.left+b.width/2-e.clientX,dy=b.top+b.height/2-e.clientY,dist=Math.sqrt(dx*dx+dy*dy)-(d.classList.contains("dim")?6:0);if(dist<bd){bd=dist;best=d}});
  if(best&&bd<=R){e.preventDefault();e.stopPropagation();best.dispatchEvent(new MouseEvent("click",{bubbles:!0}))}
},!0);
/* ===== Oct 29 2026: Vibe Map side panel (desktop) and Map/List on phones =====
   Desktop: the map takes two thirds and never gets covered. The panel walks people through three states:
   no vibe picked (the vibe grid is the hook), a vibe picked (its towns, coast order), a town picked (its card).
   S.vcard = a town card is open, S.vlist = phone list view. */
var VSUB={oldfl:"Fish houses, bait shops and no hurry",dock:"Life on and around the water",island:"Barefoot, small and slow",sophcalm:"Polished, peaceful and easy",sophhigh:"Polished with a pulse",social:"Bars, events and a crowd",active:"Trails, paddling and bikes",bluezone:"Long walks, time outside, friendly faces",walk:"Daily life on foot",remote:"Pretty towns near an airport, without the city",beaches:"Nationally ranked sand",afford:"More house for the money"};
