/* Budget and Affordability are one slider: slide right for a tighter budget. Each stop sets the price range and how much price counts */
const BUD_WORDS=["Any price","$1.5M and up","$750K to $1.5M","$500K to $750K","$350K to $500K","Under $350K"],BUD_SET=[[null,0],[4,0],[3,30],[2,50],[1,70],[0,90]];

function slBudV(){return null==S.slBud?0:5-S.slBud}
