  return `<div class="vm-lh slv-lh"><div class="slv-eb"><span class="vm-eb">${T.length} beach towns · ${SLC().length} priorities</span><button class="sl-reset" data-slreset="1"${slAnySet()?"":" disabled"}>↺ Reset</button></div><h2>What matters to you?</h2>${SL_HOW}</div>${where}<div class="sl2-grp">${(()=>{const q=S.sl.pace??50;return slRow2("sl2-pace",'data-sl="pace"',"Quiet or lively",slWord2("pace",q),q,0,100,5,q!==50)})()}${slRow2("sl2-bud","data-slb","Budget",BUD_WORDS[bv],bv,0,5,1,bv>0)}</div>${xs.length?`<p class="sl-also">Also from your answers: ${xs.map(c=>`${c[1]} <button class="linkbtn" data-slx="${c[0]}" aria-label="Remove ${c[1]}">✕</button>`).join(" · ")}</p>`:""}<div class="slv-div"></div><div class="sl-list sl2-list">${rows.replace("<b>Public schools</b>",'<b>Public schools <button type="button" class="sl2-i" data-slinfo="1" aria-expanded="false" aria-label="About public schools">i</button></b>')}<p class="sl2-note" id="sl2-edu" hidden>We average the Florida Department of Education grades (percent of points, ${EDU_YEAR}) of the nearest public elementary, middle and high schools to each town. Zoning lines vary, so check the assigned schools for any address.</p></div>${slQuiz()?'<p class="sl-redo"><button class="linkbtn" data-act="retake">Start the questions over</button></p>':""}`;
