/* ===== Nov 5 2026 PREVIEW: Vibe Map, needs not people =====
   The map asks what you need (features anyone can pick), never who you are. Everyone sees the same options.
   Vibe tiles are the 8 feelings; the practical ones (price, beaches, airport...) moved to "What you need".
   Data: MED (median home), FLOODSC (flood score, 50 towns scored, lower is safer), eduScore (FL DOE county grade), score(e,"airport"), score(e,"beach"). */
const VFEEL=["beaches","oldfl","bluezone","island","dock","sophhigh","social","sophcalm","active","walk","afford","remote"];
const NEEDS=[["school","Strong public schools"],["air","Airport within about 45 min"]];
const NBUD=[[0,"Any price"],[350,"Under $350K"],[500,"Under $500K"],[750,"Under $750K"]];
S.need=S.need||{};
/* the map's style lists (chips, tiles, counts) show only the 8 feelings; the other 4 keep their guides and town tags */
function vGroups(){return"map"===curRoute()?[["Feel",VFEEL]]:VGROUPS}
function needOn(){S.need=S.need||{};return Object.keys(S.need).some(k=>S.need[k])}
/* Nov 6 2026: "Airport within about 45 min" uses the drive time in the town's airport line (first airport named), up to 50 min; towns with no time listed keep the 1 to 5 airport score (4 or 5 passes) */
/* approximate drive times for towns whose airport line names no time (map estimates, Nov 2026) */
const AIRMIN={"30a":35,captiva:50,matlacha:35,keywest:10,fortpierce:55,flagler:30,freeport:30};
function airMin(e){if(null!=AIRMIN[e.id])return AIRMIN[e.id];const t=(e.airport||"").replace(/\b(St|Ft|Pt)\. /g,"$1 ").split(/;| or |\. /)[0],m=t.match(/about (an hour|(\d+(?:\.\d+)?)(?: to (\d+(?:\.\d+)?))? (hours?|minutes?)(?: (\d+) minutes)?)/);if(!m)return null;if("an hour"===m[1])return 60;const a=+(m[3]||m[2]);return Math.round(/hour/.test(m[4])?a*60+(+m[5]||0):a)}
function airNear(e){const m=airMin(e);return null!=m?m<=50:score(e,"airport")>=4}
function needOk(e){
  const n=S.need||{};
  if(n.bud&&!(MED[e.id]&&MED[e.id]<=n.bud))return!1;
  if(n.school&&!(eduScore(e)>=4))return!1;
  if(n.air&&!airNear(e))return!1;
  if(n.beach&&!(score(e,"beach")>=5))return!1;
  return!0;
}
function needCounts(){const q={};Object.keys(VIBES).forEach(k=>q[k]=T.filter(t=>t.vibes.includes(k)&&needOk(t)).length);return q}
function needN(){return Object.keys(S.need).filter(k=>S.need[k]).length}
/* phones: the "What you need" button, and the chip on the map once filters are on */
