/* ===== Nov 7 2026: end of walkthrough card, "Take them with you" =====
   Opens when the 5 town walkthrough finishes (not on skip). Sells the 8 page Shortlist the top5 email already sends.
   Replaces the small box on the 5th town. Tracked as popup_shown "endcard"; closing it is popup_closed. */
function matchesBox(o){
  const a=o.slice(0,5);if(!a.length)return"";
  const sent=S.sent.matches;
  const cover=`<div class="ec-stack" aria-hidden="true"><img class="sl-back" src="img/shortlist-p8.webp" alt=""><div class="sl-cover"><span class="slc-logo">Florida Coastal</span><span class="slc-ph">${art(a[0],!1)}</span><span class="slc-k">Your Florida Shortlist</span><b>Five towns that fit how you want to live.</b>${a.map((t,i)=>`<i><em>${i+1}</em>${short(t)}</i>`).join("")}</div><span class="sl-pages">8 pages</span></div>`;
  const body=sent?leadThanks("matches"):`<form class="leadform ec-form" data-lead="matches" data-key="matches">${hpField}<label for="ec-e" class="ec-lbl">Your email</label><input id="ec-e" name="email" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com" required><button class="btn btn-accent" type="submit">Email me my Shortlist</button></form>`;
  return `<div class="lmodal ec" role="dialog" aria-modal="true" aria-labelledby="lm-t"><div class="lmback" data-lmclose></div><div class="lmcard ec-card"><button class="lmx" data-lmclose aria-label="Close">&times;</button>
  <div class="ec-top">${cover}<div class="ec-hd"><span class="ec-eb">That's your ${a.length}</span><h3 id="lm-t">Take them with you</h3></div></div>
  <p class="ec-sub">${slPersonal(a)}</p>
  ${body}
  ${sent?"":`<p class="sl-from ec-from"><img src="img/mark-betsy-sq.webp" alt="" width="40" height="40"><span>We send it ourselves. <b>Mark and Betsy Scott</b>. Free, unsubscribe anytime.</span></p>`}
  <div class="lmalt ec-alt"><button class="linkbtn ec-no" data-lmclose>${sent?"Back to my towns":"No thanks, show me my towns"}</button></div>
  </div></div>`;
}

/* Nov 7 2026: flood article quiz box clicks */
document.addEventListener("click",function(e){const a=e.target.closest&&e.target.closest("[data-fq]");if(!a)return;try{track("save_tap","flood "+a.dataset.fq)}catch(x){}},!0);


